);

// ── TOAST ─────────────────────────────────────────────────────
const Toast = ({ msg, type="ok", onClose }) => (
  <div style={{ position:"fixed", bottom:24, right:24, zIndex:3000, background:type==="err"?C.crimson:C.navy, color:"white", padding:"12px 20px", borderRadius:10, boxShadow:"0 8px 30px rgba(0,0,0,.3)", display:"flex", alignItems:"center", gap:10, fontSize:14, maxWidth:360, animation:"fadeIn .3s ease" }}>
    {type==="err"?"❌":"✅"} {msg}
    <button className="btn" onClick={onClose} style={{ background:"transparent", color:"rgba(255,255,255,.7)", marginLeft:"auto", padding:2 }}><Icon name="close" size={14}/></button>
