// ══════════════════════════════════════════════════════════════
//  CARRUSEL DE FOTOS ITZ
// ══════════════════════════════════════════════════════════════
function Carrusel() {
  const [idx, setIdx] = useState(0);
  const [drag, setDrag] = useState(false);
  const [startX, setStartX] = useState(0);
  const timer = useRef(null);

  const next = useCallback(() => setIdx(i => (i+1) % CARRUSEL_FOTOS.length), []);
  const prev = () => setIdx(i => (i-1+CARRUSEL_FOTOS.length) % CARRUSEL_FOTOS.length);

  useEffect(() => {
    timer.current = setInterval(next, 5000);
    return () => clearInterval(timer.current);
  }, [next]);

  const reset = () => { clearInterval(timer.current); timer.current = setInterval(next, 5000); };

  const foto = CARRUSEL_FOTOS[idx];

  return (
    <div style={{ position:"relative", width:"100%", height:"100%", overflow:"hidden" }}
      onMouseDown={e => { setDrag(true); setStartX(e.clientX); }}
      onMouseUp={e => {
        if (!drag) return; setDrag(false);
        const diff = startX - e.clientX;
        if (Math.abs(diff) > 50) { diff > 0 ? next() : prev(); reset(); }
      }}
      onTouchStart={e => setStartX(e.touches[0].clientX)}
      onTouchEnd={e => {
        const diff = startX - e.changedTouches[0].clientX;
        if (Math.abs(diff) > 50) { diff > 0 ? next() : prev(); reset(); }
      }}>
      {/* Imagen */}
      <img key={idx} src={foto.src} alt={foto.titulo}
        style={{ width:"100%", height:"100%", objectFit:"cover", animation:"fadeIn .8s ease" }}
        onError={e => { e.target.style.display="none"; }}/>
      {/* Fallback gradient cuando no hay imagen */}
      <div style={{ position:"absolute", inset:0, background:`linear-gradient(135deg,${C.navy},${C.mid},${C.steel})`, zIndex:-1 }}/>
      {/* Overlay */}
      <div style={{ position:"absolute", inset:0, background:"linear-gradient(to top, rgba(10,8,35,.8) 0%, rgba(10,8,35,.3) 50%, transparent 100%)" }}/>
      {/* Texto */}
      <div style={{ position:"absolute", bottom:60, left:0, right:0, textAlign:"center", padding:"0 20px" }}>
        <div style={{ fontFamily:"'Playfair Display',serif", fontSize:"clamp(20px,3vw,36px)", color:"white", fontWeight:700, textShadow:"0 2px 12px rgba(0,0,0,.5)" }}>{foto.titulo}</div>
        <div style={{ fontSize:14, color:"rgba(255,255,255,.75)", marginTop:6, letterSpacing:".05em" }}>{foto.subtitulo}</div>
      </div>
      {/* Controles */}
      <button className="btn" onClick={() => { prev(); reset(); }}
        style={{ position:"absolute", left:12, top:"50%", transform:"translateY(-50%)", background:"rgba(255,255,255,.15)", backdropFilter:"blur(8px)", color:"white", padding:"10px", borderRadius:"50%", display:"flex" }}>
        <Icon name="chevL" size={20}/>
      </button>
      <button className="btn" onClick={() => { next(); reset(); }}
        style={{ position:"absolute", right:12, top:"50%", transform:"translateY(-50%)", background:"rgba(255,255,255,.15)", backdropFilter:"blur(8px)", color:"white", padding:"10px", borderRadius:"50%", display:"flex" }}>
        <Icon name="chevR" size={20}/>
      </button>
      {/* Dots */}
      <div style={{ position:"absolute", bottom:20, left:0, right:0, display:"flex", justifyContent:"center", gap:8 }}>
        {CARRUSEL_FOTOS.map((_, i) => (
          <button key={i} className="btn" onClick={() => { setIdx(i); reset(); }}
            style={{ width:i===idx?24:8, height:8, borderRadius:4, background:i===idx?"white":"rgba(255,255,255,.4)", padding:0, transition:"all .3s" }}/>
        ))}
      </div>
    </div>
  );
}

// ══════════════════════════════════════════════════════════════
//  LIGHTBOX — VISUALIZADOR CON MARCA DE AGUA
// ══════════════════════════════════════════════════════════════
function Lightbox({ foto, fotos, onClose, onNav }) {
  const [zoom, setZoom]   = useState(1);
  const [meta, setMeta]   = useState(true);
  const [pos, setPos]     = useState({ x:0, y:0 });
  const [drag, setDrag]   = useState(false);
  const [ds, setDs]       = useState({ x:0, y:0 });
  const [descargando, setDescargando] = useState(false);

  const colFotos = fotos.filter(f => f.coleccion_id === foto.coleccion_id);
  const idx      = colFotos.findIndex(f => f.id === foto.id);
  const src      = storageUrl(foto.url_web || foto.url_original);

  useEffect(() => {
    const h = e => {
      if (e.key === "Escape")      onClose();
      if (e.key === "ArrowRight") { onNav(1);  setZoom(1); setPos({x:0,y:0}); }
      if (e.key === "ArrowLeft")  { onNav(-1); setZoom(1); setPos({x:0,y:0}); }
    };
    window.addEventListener("keydown", h);
    return () => window.removeEventListener("keydown", h);
  }, [foto]);

  // ── Descarga con marca de agua ────────────────────────────
  const descargarConMarca = async () => {
    if (!src) return;
    setDescargando(true);
    try {
      const response = await fetch(src);
      const blob     = await response.blob();
      const imgUrl   = URL.createObjectURL(blob);
      const img      = new Image();
      img.crossOrigin = "anonymous";
      img.onload = () => {
        const canvas  = document.createElement("canvas");
        canvas.width  = img.width;
        canvas.height = img.height;
        const ctx     = canvas.getContext("2d");
        ctx.drawImage(img, 0, 0);

        // Marca de agua diagonal repetida
        ctx.save();
        ctx.globalAlpha = 0.3;
        ctx.fillStyle   = "white";
        const fontSize  = Math.max(img.width * 0.035, 20);
        ctx.font        = `bold ${fontSize}px Arial`;
        ctx.textAlign   = "center";
        for (let i = -3; i <= Math.ceil(img.width/280)+3; i++) {
          for (let j = -3; j <= Math.ceil(img.height/180)+3; j++) {
            ctx.save();
            ctx.translate(i*280, j*180);
            ctx.rotate(-Math.PI/6);
            ctx.fillText("© Fototeca ITZ", 0, 0);
            ctx.restore();
          }
        }

        // Barra inferior
        const barH = Math.max(img.height * 0.055, 32);
        ctx.globalAlpha = 0.8;
        ctx.fillStyle   = C.navy;
        ctx.fillRect(0, img.height - barH, img.width, barH);
        ctx.globalAlpha = 1;
        ctx.fillStyle   = "white";
        const fs2 = Math.max(fontSize * 0.45, 12);
        ctx.font  = `${fs2}px Arial`;
        ctx.textAlign = "left";
        ctx.fillText(
          `© Fototeca ITZ · ${foto.derechos||"Todos los derechos reservados"} · ${foto.autor||""} ${foto.anio||""}`,
          16, img.height - barH*0.25
        );

        // Logo ITZ (texto si no hay imagen)
        ctx.textAlign = "right";
        ctx.fillText("Instituto Tecnológico de Zacatecas", img.width - 16, img.height - barH*0.25);
        ctx.restore();

        canvas.toBlob(b => {
          const url  = URL.createObjectURL(b);
          const link = document.createElement("a");
          link.href     = url;
          link.download = `${foto.titulo||"imagen"}_ITZ.jpg`;
          link.click();
          URL.revokeObjectURL(url);
          URL.revokeObjectURL(imgUrl);
          setDescargando(false);
        }, "image/jpeg", 0.82);
      };
      img.onerror = () => setDescargando(false);
      img.src = imgUrl;
    } catch(e) { alert("Error: "+e.message); setDescargando(false); }
  };

  return (
    <div style={{ position:"fixed", inset:0, zIndex:1000, background:"rgba(10,8,35,.97)", display:"flex", flexDirection:"column" }}
      onContextMenu={e => e.preventDefault()}>
      {/* Barra superior */}
      <div style={{ display:"flex", alignItems:"center", justifyContent:"space-between", padding:"14px 20px", borderBottom:`1px solid rgba(255,255,255,.08)` }}>
        <div style={{ display:"flex", alignItems:"center", gap:12 }}>
          <span style={{ color:C.steel, fontSize:12, letterSpacing:".1em", textTransform:"uppercase" }}>{idx+1} / {colFotos.length}</span>
          <span style={{ color:"white", fontFamily:"'Cormorant Garamond',serif", fontSize:18 }}>{foto.titulo}</span>
        </div>
        <div style={{ display:"flex", gap:8 }}>
          <button className="btn" onClick={() => setZoom(z => Math.min(4,z+.5))} style={{ background:"rgba(255,255,255,.08)", color:"white", padding:"7px", borderRadius:8 }}><Icon name="zoomIn" size={16}/></button>
          <button className="btn" onClick={() => setZoom(z => Math.max(1,z-.5))} style={{ background:"rgba(255,255,255,.08)", color:"white", padding:"7px", borderRadius:8 }}><Icon name="zoomOut" size={16}/></button>
          <button className="btn" onClick={() => setMeta(v=>!v)} style={{ background:meta?"rgba(103,156,188,.3)":"rgba(255,255,255,.08)", color:"white", padding:"7px", borderRadius:8 }}><Icon name="info" size={16}/></button>
          {foto.descargable && (
            <button className="btn" onClick={descargarConMarca} disabled={descargando}
              style={{ background:`rgba(145,108,63,.4)`, color:"white", padding:"7px 14px", borderRadius:8, fontSize:12, display:"flex", alignItems:"center", gap:6, fontWeight:500, opacity:descargando?.6:1 }}>
              {descargando ? <Spinner small/> : <Icon name="download" size={14}/>}
              {descargando ? "Generando…" : "Descargar"}
            </button>
          )}
          <button className="btn" onClick={onClose} style={{ background:"rgba(193,23,32,.3)", color:"white", padding:"7px", borderRadius:8 }}><Icon name="close" size={18}/></button>
        </div>
      </div>
      {/* Imagen */}
      <div style={{ flex:1, display:"flex", alignItems:"center", justifyContent:"center", position:"relative", overflow:"hidden" }}
        onWheel={e => { e.preventDefault(); setZoom(z => Math.min(4,Math.max(1,z-e.deltaY*.002))); }}
        onMouseDown={e => { if(zoom>1){ setDrag(true); setDs({x:e.clientX-pos.x,y:e.clientY-pos.y}); }}}
        onMouseMove={e => { if(drag) setPos({x:e.clientX-ds.x,y:e.clientY-ds.y}); }}
        onMouseUp={() => setDrag(false)}>
        <button className="btn" onClick={() => { onNav(-1); setZoom(1); setPos({x:0,y:0}); }}
          style={{ position:"absolute", left:16, zIndex:10, background:"rgba(255,255,255,.1)", color:"white", padding:"12px", borderRadius:"50%", display:"flex" }}>
          <Icon name="chevL" size={22}/>
        </button>
        {src
          ? <img src={src} alt={foto.titulo} draggable={false}
              style={{ maxWidth:"90%", maxHeight:"80vh", objectFit:"contain", transform:`scale(${zoom}) translate(${pos.x/zoom}px,${pos.y/zoom}px)`, transition:drag?"none":".2s", cursor:zoom>1?"grab":"zoom-in", userSelect:"none" }}/>
          : <div style={{ color:"rgba(255,255,255,.3)", textAlign:"center" }}><Icon name="photo" size={64} color="rgba(255,255,255,.1)"/><div style={{ marginTop:12, fontSize:13 }}>Sin imagen</div></div>
        }
        <button className="btn" onClick={() => { onNav(1); setZoom(1); setPos({x:0,y:0}); }}
          style={{ position:"absolute", right:16, zIndex:10, background:"rgba(255,255,255,.1)", color:"white", padding:"12px", borderRadius:"50%", display:"flex" }}>
          <Icon name="chevR" size={22}/>
        </button>
      </div>
      {/* Metadatos */}
      {meta && (
        <div style={{ background:"rgba(28,20,109,.55)", backdropFilter:"blur(20px)", padding:"16px 24px", borderTop:`1px solid rgba(255,255,255,.08)`, display:"flex", gap:28, flexWrap:"wrap" }}>
          {[["Autor",foto.autor],["Año",foto.anio],["Lugar",foto.lugar],["Edificio",foto.edificio],["Archivo",foto.tipo_archivo],["Derechos",foto.derechos]].map(([k,v]) => (
            <div key={k}>
              <div style={{ fontSize:10, letterSpacing:".1em", textTransform:"uppercase", color:C.steel, marginBottom:2 }}>{k}</div>
              <div style={{ fontSize:13, color:"white" }}>{v||"—"}</div>
            </div>
          ))}
          {foto.descripcion && (
            <div style={{ flex:1, minWidth:220 }}>
              <div style={{ fontSize:10, letterSpacing:".1em", textTransform:"uppercase", color:C.steel, marginBottom:2 }}>Descripción</div>
              <div style={{ fontSize:13, color:"rgba(255,255,255,.8)" }}>{foto.descripcion}</div>
            </div>
          )}
          {foto.keywords && (
            <div style={{ flex:1, minWidth:200 }}>
              <div style={{ fontSize:10, letterSpacing:".1em", textTransform:"uppercase", color:C.steel, marginBottom:4 }}>Palabras clave</div>
              <div style={{ display:"flex", flexWrap:"wrap", gap:4 }}>
                {String(foto.keywords).split(",").map(k => (
                  <span key={k} style={{ background:"rgba(103,156,188,.25)", color:C.lavender, padding:"2px 8px", borderRadius:10, fontSize:11 }}>{k.trim()}</span>
                ))}
              </div>
            </div>
          )}
        </div>
      )}
    </div>
  );
}

